INSERT INTO hrm_education (
  education_key, person_key, employee_no,
  school_type_code, admission_date, graduation_date,
  school_name, graduation_status_code, degree_code, field_code,
  major, country_code, is_final_education,
  del_yn, reg_user, reg_dtm, reg_user_ip, upd_user, upd_dtm, upd_user_ip
)
SELECT
  encode(gen_random_bytes(40), 'hex') as education_key,
  hp.person_key,
  ed.emp_no as employee_no,
  ed.school_type_code,
  ed.admission_date,
  ed.graduation_date,
  ed.school_name,
  ed.graduation_status_code,
  ed.degree_code,
  ed.field_code,
  ed.major,
  ed.country_code,
  ed.is_final_education,
  'N' as del_yn,
  'SYSTEM' as reg_user,
  NOW() as reg_dtm,
  '127.0.0.1' as reg_user_ip,
  'SYSTEM' as upd_user,
  NOW() as upd_dtm,
  '127.0.0.1' as upd_user_ip
FROM education_data ed
INNER JOIN hrm_person hp ON hp.employee_no = ed.emp_no
ON CONFLICT (education_key) DO NOTHING;
